"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6374],{49127:e=>{e.exports=JSON.parse('{"functions":[{"name":"topOf","desc":"The entry that owns the selection: the highest rank, the newest on a tie.","params":[{"name":"list","desc":"","lua_type":"{ Entry }"}],"returns":[{"desc":"","lua_type":"Entry?\\n"}],"function_type":"static","source":{"line":99,"path":"src/Client/Util/GamepadSelection.luau"}},{"name":"topRank","desc":"The rank of the entry that owns the selection, 0 with nothing up. A bind\\nthat moves the selection (the HUD focus) passes while something above\\nits own layer is on top.","params":[],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":120,"path":"src/Client/Util/GamepadSelection.luau"}},{"name":"push","desc":"Adds a surface. Seeds it when it lands on top.","params":[{"name":"root","desc":"","lua_type":"GuiObject"},{"name":"options","desc":"","lua_type":"{ current: Options }"}],"returns":[{"desc":"","lua_type":"Entry\\n"}],"function_type":"static","source":{"line":297,"path":"src/Client/Util/GamepadSelection.luau"}},{"name":"remove","desc":"Removes a surface and hands the selection on (see the header).","params":[{"name":"entry","desc":"","lua_type":"Entry"}],"returns":[],"function_type":"static","source":{"line":322,"path":"src/Client/Util/GamepadSelection.luau"}}],"properties":[],"types":[],"name":"GamepadSelection","desc":"GamepadSelection \u2014 who holds the gamepad selection, and what B does.\\n\\nEvery surface that wants the selection while a gamepad is in use (a\\nwindow, a dialog, a prompt, the HUD, a panel) pushes an entry with its\\nroot and a layer; useGamepadSelection does it from React. The entry on\\ntop owns the selection: the highest layer, the newest on a tie. Views\\nmounts portals in no set order, so the layer, not the mount order,\\nsettles a prompt and a panel that show at once.\\n\\n  \u2022 Seeding: the top entry\'s `seed` object, else GuiService:Select(root),\\n    after `seedDelay` (a window\'s slide-in), retried each frame for about\\n    half a second until the selection is inside the root. Select only\\n    looks at on-screen objects, so a seed during the slide finds nothing.\\n  \u2022 Fences (applied by the hook): \\"stop\\" keeps the D-pad inside the root;\\n    \\"soft\\" prefers the root but lets the D-pad leave it.\\n  \u2022 B: one shared action at High priority, bound while any entry is up.\\n    It goes to the highest entry with an `onBack` and passes otherwise.\\n    In Studio with ForceInputDevice \\"gamepad\\", Backspace stands in for\\n    B, which Studio\'s automation can\'t send.\\n  \u2022 Removal, while the selection is inside the root or gone: back to what\\n    was selected before the entry if that\'s still usable, and inside the\\n    new top entry unless that one\'s fence is soft (the HUD\'s D-pad roams\\n    past its column, so a chip that opened a window gets it back); else\\n    to the new top entry; else nowhere. Off a gamepad, it\'s cleared.\\n  \u2022 A lost selection re-seeds the top entry when the selected object was\\n    destroyed or hidden (an Equip that turns into a pill, a list that\\n    refreshed). A selection cleared while its object still stands means\\n    something else took it, like a Roblox prompt, so it\'s left alone.","source":{"line":36,"path":"src/Client/Util/GamepadSelection.luau"}}')}}]);